import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class GoodFileAccess {
    public static void main(String[] args) {
        // Simulate user input for demonstration
        String userInput = "../secret/data.txt"; 

        try {
            // Use the parent directory as the base safe path
            Path baseDir = Paths.get("/safe/uploads"); 

            // Construct the full path using the user input relative to the base dir
            Path requestedPath = baseDir.resolve(userInput).normalize();

            // Ensure the resolved path is still within the intended base directory
            // This prevents directory traversal attacks (e.g., ../../etc/passwd)
            if (!requestedPath.startsWith(baseDir)) {
                throw new SecurityException("Access denied: path escapes allowed directory");
            }

            // Now safe to check existence and read
            if (Files.exists(requestedPath)) {
                System.out.println("File exists: " + requestedPath.toAbsolutePath());
            } else {
                System.out.println("File not found.");
            }
        } catch (SecurityException e) {
            System.err.println("Error: " + e.getMessage());
        }
    }
}
